// Custom for Home Billiards
// -----------------------------------------------------------------------------

iframe {
    max-width: 100%;
}

table {
	margin-bottom: 1.5rem;

	thead {
		td {
			font-weight: bold;
		}
	}

	th, td {
		padding: 0.3rem 0 0.3rem 2rem;
		vertical-align: top;

		&:first-child {
			padding-left: 0;
		}
	}
}

@media screen and (max-width: 600px) {
	table {
		thead {
			display: none;
		}

		tr {
			padding-top: 2rem;

			td {
				display: flex;
				padding-left: 0;

				&:first-child {
					padding-top: 1.5rem;
				}
			}

			&:first-child {
				td {
					padding-top: 0;
				}
			}

			td::before {
				content: attr(aria-label);
				font-weight: bold;
				width: 120px;
				min-width: 120px;
				padding-right: 0.3rem;
			}
		}
	}
}

.navUser .contactLink {
	font-size: 18px;
	margin: 0 10px 0 0;
}

@media (max-width: 991px) {
	.navUser .contactLink {
		display: none;
	}

	.heroCarousel {
		display: none;
	}
}

#pool-table-calculator {
    max-width: 500px;
    margin: 0 auto;

