    font-weight: bold;
    border-radius:0;
}




//-----------------------------------------------------------------------------OVERRRIDE HEADER PART -----------------------------------//

.topBar{
    background-color:#30333F;
    .anncmnt.textCenter{
        display:flex;
        align-items:center;
        justify-content: space-between;
        padding-top:0;
        padding-bottom:0; 
        @media(min-width:992px){
            padding-left:29px;
        }
        @media(max-width:991px){
            justify-content: center;
            padding-top:10px;
            padding-bottom:10px;
        }
        div:first-of-type{
