        }
        .main-nav{
            background-color:transparent;
            border-bottom:none;
            a.navPages-action{
                color:white !important;
            }
        }
    }
    
}
.navPages-container{
    .navPages-action{
        padding:10px 1rem;
        font-weight:600;
    }
}
.container-header-aoc{
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-left: 20px;
    padding-right: 20px;
    border: 1px solid #ccc;
    border-left: none;
    border-right: none;
    box-shadow: 0px 3px 10px rgba(0, 0, 0, 0.2);
    @media(max-width:991px){
        border:none;
    }

    a#cc{
        text-transform:capitalize;
        font-size:16px;
        width: 184px;
        text-align: center;
            @media(max-width:991px){
        display:none;
    }
            display: block;
            height: 100%;
            cursor:pointer;
            background-color: rgba(112, 116, 145, 1);
            padding: 12px 2.78571rem;
            color: white; 
            &:hover{
                background-color: rgb(117, 124 ,179);
            }
    }
}

.header-holder{
    padding:10px 20px;
    @media(max-width:991px){
        padding-top:0;
    }
    flex-direction:row-reverse;
    justify-content:space-between;
    @media(max-width:991px){
        justify-content:center;
    }
    .header-logo.header-logo--center{
        width:23%;
        padding-top:8px;
        padding-bottom:8px;
        @media(max-width:991px){
            justify-content: center;
            padding-top:0;
        }
        a.header-logo__link{
            margin-left:0;
            @media(max-width:991px){
                margin:0;
            }
        }
       
    }
     .container-after-logo{
            width:77%;
            #search_query{
                border-radius:4px;
                border-color: #686B7A;
                height:50px;
                &:hover{
                    border-color: #313440;
                }
            }
            @media(min-width:992px){
                .navUser-cart{
                    margin-right:14px;
                }
            }
            @media(max-width:991px){
                width:0;
                .label-cart{
                    display:none;
                }
                .navUser-cart{
                    position:absolute;
                    right:8px;
                }
            }
                display: flex;
                align-items: center;
                justify-content: space-between;
                form{
                    width:70%;
                    margin:0;
                    position:relative;
                    button{
                        position:absolute;
                        top:50%;
                        transform:translateY(-50%);
                        right:0;
                        padding:11px;
                        margin:0;
                        border:none;
                        display:flex;
                        align-items:center;
                        justify-content: center;
                        span{
                            margin-right:8px;
                            color:#707491;
                        } 
                        &:hover{
                            span{
                                color:#313440;
                                font-weight:600;
                            }
