    border: 1px solid #e5e7eb;
    border-radius: 10px;
    margin-bottom: 12px;
    background: #fff;
    overflow: hidden;
  }

  .hb-faq summary {
    cursor: pointer;
    list-style: none;
    padding: 14px 16px;
  }

  .hb-faq summary::-webkit-details-marker { display: none; }

  .hb-faq summary h2.faq-heading {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: space-between;
  }

  .hb-faq summary h2.faq-heading::after {
    content: "＋";
    font-weight: 700;
    margin-left: 12px;
  }

  .hb-faq details[open] summary h2.faq-heading::after {
    content: "－";
  }

  .hb-faq .hb-faq__content {
    padding: 0 16px 16px;
  }

  .hb-faq .hb-faq__content p {
    margin-top: 10px;
  }

